:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --btn-bg: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-active: #0a2647;
  --focus: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--accent);
  margin-bottom: 16px;
  text-transform: uppercase;
}

.mode-indicator {
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--muted);
  margin-bottom: 8px;
  text-transform: uppercase;
}

.countdown {
  font-size: 4rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 16px 0 24px;
  color: var(--text);
  line-height: 1.1;
  word-break: break-all;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
  background: var(--btn-bg);
  color: var(--text);
  border: 3px solid var(--accent);
  border-radius: 0;
  padding: 12px 20px;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  min-width: 100px;
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:active {
  background: var(--btn-active);
  transform: translate(2px, 2px);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  min-width: 80px;
  padding: 8px 16px;
  font-size: 0.9rem;
  opacity: 0.7;
}

.mode-btn.active {
  opacity: 1;
  background: var(--accent);
  color: var(--bg);
}

.mode-btn.active:hover {
  background: var(--accent);
  filter: brightness(1.1);
}

@media (max-width: 400px) {
  .countdown {
    font-size: 3rem;
  }
  .btn {
    min-width: 80px;
    padding: 10px 14px;
    font-size: 0.9rem;
  }
  .card {
    padding: 24px 16px;
  }
}

(function () {
  'use strict';

  const WORK_DURATION = 25 * 60; // 25 minutes
  const BREAK_DURATION = 5 * 60; // 5 minutes

  const state = {
    mode: 'work',
    remaining: WORK_DURATION,
    running: false,
    intervalId: null,
    endTime: null
  };

  const countdownEl = document.getElementById('countdown');
  const modeIndicatorEl = document.getElementById('modeIndicator');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workModeBtn');
  const breakModeBtn = document.getElementById('breakModeBtn');

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function updateDisplay() {
    countdownEl.textContent = formatTime(state.remaining);
    modeIndicatorEl.textContent = state.mode === 'work' ? 'WORK' : 'BREAK';
    startPauseBtn.textContent = state.running ? 'PAUSE' : 'START';
    startPauseBtn.setAttribute('aria-label', state.running ? 'Pause timer' : 'Start timer');
  }

  function setMode(mode) {
    if (state.running) {
      stopTimer();
    }
    state.mode = mode;
    state.remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
    workModeBtn.classList.toggle('active', mode === 'work');
    workModeBtn.setAttribute('aria-pressed', mode === 'work' ? 'true' : 'false');
    breakModeBtn.classList.toggle('active', mode === 'break');
    breakModeBtn.setAttribute('aria-pressed', mode === 'break' ? 'true' : 'false');
    updateDisplay();
  }

  function tick() {
    const now = Date.now();
    const remaining = Math.max(0, Math.round((state.endTime - now) / 1000));
    if (remaining !== state.remaining) {
      state.remaining = remaining;
      updateDisplay();
    }
    if (remaining <= 0) {
      stopTimer();
      const nextMode = state.mode === 'work' ? 'break' : 'work';
      setMode(nextMode);
    }
  }

  function startTimer() {
    if (state.running) return;
    state.running = true;
    state.endTime = Date.now() + state.remaining * 1000;
    state.intervalId = setInterval(tick, 200);
    updateDisplay();
  }

  function stopTimer() {
    if (!state.running) return;
    state.running = false;
    clearInterval(state.intervalId);
    state.intervalId = null;
    updateDisplay();
  }

  function toggleTimer() {
    if (state.running) {
      stopTimer();
    } else {
      startTimer();
    }
  }

  function resetTimer() {
    stopTimer();
    state.remaining = state.mode === 'work' ? WORK_DURATION : BREAK_DURATION;
    updateDisplay();
  }

  startPauseBtn.addEventListener('click', toggleTimer);
  resetBtn.addEventListener('click', resetTimer);
  workModeBtn.addEventListener('click', function () { setMode('work'); });
  breakModeBtn.addEventListener('click', function () { setMode('break'); });

  updateDisplay();
})();
